{
        struct hdr_field* hf;
        char* tmp;
        char* rest;
        char* end;
        hdr_flags_t orig_flag;

        end=msg->buf+msg->len;
        tmp=msg->unparsed;

        if (unlikely(next)) {
                orig_flag = msg->parsed_flag;
                msg->parsed_flag &= ~flags;
        } else {
                orig_flag=0;
        }

